import{_ as o,c as r,o as n,a2 as s}from"./chunks/framework.CHomSxuB.js";const l=JSON.parse('{"title":"足球信号雷达","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/index.md","filePath":"足球信号雷达/index.md"}'),a={name:"足球信号雷达/index.md"};function e(d,t,g,u,p,q){return n(),r("div",null,t[0]||(t[0]=[s('<h1 id="足球信号雷达" tabindex="-1">足球信号雷达 <a class="header-anchor" href="#足球信号雷达" aria-label="Permalink to &quot;足球信号雷达&quot;">​</a></h1><blockquote><p>一句话：<strong>一个只研究赔率信号、不碰下注的验证体系</strong>——把&quot;赔率背后谁在动、动得对不对&quot;拆成可检验的信号， 用样本外（OOS）时间换证据，允许并预期&quot;信号失效&quot;。 2026-09-01 起项目已整体移除下注相关代码，只保留<strong>信号研究</strong>与<strong>读盘展示</strong>两条腿。</p></blockquote><p>本板块与 <a href="/A股量化验证/">A股量化验证</a> 是同一套统计纪律在不同市场的落地： A 股验证&quot;涨停生态里的盘面传言&quot;，足球这边验证&quot;赔率变动里的市场信号&quot;——都是<strong>先冻结规则 → 只跑不调 → 如实落盘</strong>。</p><hr><h2 id="这个系列在做什么" tabindex="-1">这个系列在做什么 <a class="header-anchor" href="#这个系列在做什么" aria-label="Permalink to &quot;这个系列在做什么&quot;">​</a></h2><p>足球比赛的赔率里藏着三个问题：<strong>钱最终站在哪一边</strong>（方向）、<strong>大家是不是一条心</strong>（分歧）、<strong>临场有没有变</strong>（走势）。 V5 信号体系就是把这三点变成可统计的机器规则，然后逐场对账——每一条信号都要回答： &quot;触发后，不败方向到底命中了几成，相比赔率自己隐含的概率，多出来的部分扣不扣得住抽水。&quot;</p><p>方法论上的红线与 A 股一致：<strong>样本不足不评价、同一段历史挖参数=自欺、回测说的不算 OOS 说了才算</strong>。</p><hr><h2 id="战线状态-截至-2026-11-08" tabindex="-1">战线状态（截至 2026-11-08） <a class="header-anchor" href="#战线状态-截至-2026-11-08" aria-label="Permalink to &quot;战线状态（截至 2026-11-08）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td><strong>V5 信号体系</strong>（现役 4 信号）</td><td>方向级信号：定盘星背离 / 弱势弃守 ×2 / 准冷门震荡</td><td>🟡 OOS 观测中（逐日对账；VETO 112 场 / <strong>+9.4pp</strong>，长期方向仍向下但短期在 +9.1~9.4 之间徘徊；两条 DRIFT 稳在 +3.1 / +2.4pp；QUAKE 41 场 / +1.6pp 超额转正。<strong>两条更硬的诊断：10-30 扣掉价位偏差后四条信号的增量 edge 全部归零；11-07 扣掉抽水后三条为负、唯一为正的 VETO 也只有 +3.69%</strong>）</td></tr><tr><td>影子轨（对照取证）</td><td>定盘星背离的&quot;符号修正对照&quot;版，纯观测</td><td>📝 观测中（<strong>121 场 / 85.1% / +3.5pp</strong>，低位徘徊；按建轨规则仅记账不裁决，是否收口待裁决）</td></tr><tr><td>下注/资金层</td><td>胜平负分注、仓位、爆仓治理等</td><td>🔒 2026-09-01 整体移除（历史回放为负期望）</td></tr><tr><td>读盘与展示</td><td>每日竞彩报告站（公开）：市场状态红绿灯</td><td>🟢 运营中（展示层，非交易建议；含运维稳定性沉淀 + &quot;信号被静默吞掉&quot;的关联 bug 修复 + <strong>保活机制核查：不存在系统服务，实际是每 5 分钟的计划任务，已禁用</strong>）</td></tr><tr><td>方法论沉淀</td><td>逐场结算 / 亚盘水位→概率 / 校准检验 / 符号反转复盘 / 超额口径核对 / 显著性检验与聚类 bootstrap / &quot;叠加&quot;证伪 / 同价位匹配基线 / 滚动窗口的日期口径 / <strong>抽水宽度这个常数</strong></td><td>📝 已沉淀（踩坑换来的，见方法论篇）</td></tr></tbody></table><blockquote><p>注：足球线当前<strong>不存在任何&quot;已转正可执行&quot;的生产信号</strong>。V5 四信号全部处于 OOS 观察期。 SSS_VETO（定盘星背离）已于 09-13 走完 50 场判据线，此后样本继续增加、数字整体回落： 56 场 / 91.1% / +16.1pp（到线当日）→ 65 场 / 87.7% / +12.3pp（09-27）→ 73 场 / 89.0% / +13.4pp（10-04） → 88 场 / 87.5% / +12.3pp（10-18）→ 94 场 / 88.3% / +13.0pp（10-24） → 101 场 / 87.1% / +11.9pp（10-27）→ 106 场 / 85.8% / +10.6pp（10-29） → 109 场 / 84.4% / +9.1pp（11-01）→ <strong>112 场 / 84.8% / +9.4pp（11-08）</strong>。 <strong>注意退潮不是单调下行</strong>：10-04 那次回摆（+13.4pp）在两周后<strong>精确退回到 09-27 的 +12.3pp</strong>； 10-24 之后是到线以来最陡的一段下行（+13.0 → +9.1pp），<strong>但 11-01 之后的 3 场又小幅回摆到 +9.4pp</strong>—— n 只加了 3，这个回摆什么都证明不了。<strong>长期方向向下、短期在低位徘徊，是两句不同的话。</strong><strong>到线只等于取得谈转正的资格</strong>，转正是规则/定位层面的变更，须用户裁决并留预注册卷宗——<strong>目前未转正</strong>。</p><p><strong>三轮诊断把&quot;超额&quot;这件事拆到了底</strong>： ①2026-10-21 算置信区间 → VETO 是当时唯一统计显著的，两条 DRIFT 的区间跨 0； ②2026-10-30 扣掉&quot;同价位基准&quot; → <strong>四条信号的增量 edge 全部归零</strong>（+3.1pp 里约 2.1pp 是价位校准偏差）； ③<strong>2026-11-07 扣掉抽水</strong> → 报告超额与真实赔率 ROI 之间的差是一个<strong>几乎恒定的 7.5pp</strong>， 于是<strong>三条信号的真实 ROI 为负，唯一为正的 VETO 也只有 +3.69%，且这 +3.69% 基本来自 8 月</strong>。 详见 <a href="./1-V5信号体系与考决.html">1-V5信号体系与考决</a> §八 / §九，方法见 <a href="./3-方法论沉淀.html">3-方法论沉淀</a> §九 / §十一。</p><p><strong>这三轮的顺序值得注意</strong>：先问&quot;这个数是不是 0&quot;，再问&quot;这个数里有多少是价格带来的&quot;，最后问&quot;剩下的够不够付成本&quot;。 <strong>每问一次，结论就弱一层，而每一次用的都是同一批数据。</strong></p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇</th><th>内容</th></tr></thead><tbody><tr><td><a href="./1-V5信号体系与考决.html">1-V5信号体系与考决</a></td><td>V5 重建背景、2026-08-21 冻结考决（5 规则→4 活 1 死）、四信号语义与最新 OOS 状态、统计显著性与聚类 bootstrap、同价位基准下&quot;增量 edge 归零&quot;、<strong>真实赔率 ROI 与 7.5pp 抽水宽度</strong></td></tr><tr><td><a href="./2-历史战线与下注层废弃.html">2-历史战线与下注层废弃</a></td><td>旧裁判层全链路回放结论、爆仓与过拟合教训、下注层整体移除决策</td></tr><tr><td><a href="./3-方法论沉淀.html">3-方法论沉淀</a></td><td>均值陷阱、逐场结算、亚盘水位→概率方法学、欧亚同向观测、&quot;符号反转&quot;复盘、&quot;超额&quot;口径核对、显著性检验与聚类 bootstrap、&quot;多信号叠加&quot;证伪、基准必须同价位匹配、滚动窗口必须按日期、<strong>抽水宽度：超额为正离能赚有多远</strong></td></tr><tr><td><a href="./4-读盘与展示.html">4-读盘与展示</a></td><td>公开报告站的定位收敛：从&quot;信号&quot;到&quot;市场状态观察仪&quot;；展示层三种&quot;静默失败&quot;的运维复盘（含&quot;信号被吞&quot;的关联 bug 定位与修复）；<strong>保活机制核查（没有系统服务，只有计划任务）</strong></td></tr></tbody></table><hr><h2 id="证据语言约定" tabindex="-1">证据语言约定 <a class="header-anchor" href="#证据语言约定" aria-label="Permalink to &quot;证据语言约定&quot;">​</a></h2><ul><li>所有命中率/超额都标注 <strong>n（场次）与统计日期</strong>；样本不足只描述、不裁决；</li><li><strong>命中 = 不败方向命中</strong>（如&quot;主不败/客不败&quot;），不是&quot;赢盘/赢球&quot;，口径在每篇开头写明；</li><li><strong>超额 = 命中率 − 赔率隐含概率</strong>（去水后），衡量&quot;信号比市场多知道多少&quot;；</li><li>区分 <strong>证据（回测/OOS 数据）</strong> 与 <strong>叙事（机理推测）</strong>，后者不作结论引用。</li></ul><hr><blockquote><p>⚠️ <strong>免责声明</strong>：本系列仅作赔率数据与信号统计研究，<strong>不构成任何购买推荐</strong>。 参与竞彩请到线下合法渠道，理性娱乐；未满 18 周岁不得参与。</p></blockquote>',19)]))}const i=o(a,[["render",e]]);export{l as __pageData,i as default};
